import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [n, cap] = lines[0].split(" ").map(Number);

// dp[w] = 重さの合計が w 以下のときの価値の最大値
const dp = new Array(cap + 1).fill(0);
for (let i = 1; i <= n; i++) {
  const [wi, vi] = lines[i].split(" ").map(Number);
  // 重い側から更新すると、同じ品物を 2 回使わずに済む
  for (let w = cap; w >= wi; w--) {
    dp[w] = Math.max(dp[w], dp[w - wi] + vi);
  }
}
console.log(dp[cap]);
